  val IsoFormat = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat = "yyyy-MM-dd"

  override def tokenize(value: Either[java.time.LocalDateTime, java.time.LocalDate]): Token = {
    val formatted = value match {
      case Left(dateTime) =>
        formatStr.getOrElse(IsoFormat)
        dateTime.format(java.time.format.DateTimeFormatter.ofPattern(formatStr.getOrElse(IsoFormat)))

      case Right(date) =>
        date.format(java.time.format.DateTimeFormatter.ofPattern(formatStr.getOrElse(DateFormat)))
    }
    Token(formatted, TokenType.TEMPORAL)
  }
}

