/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Int, (Either[Float, BigDecimal], String)]] {

  override def tokenize(value: Either[Int, (Either[Float, BigDecimal], String)]): Token = {
    value match {
      case Left(intValue) =>
        Token(intValue.toString, TokenType.NUMERIC, Map("originalType" -> "Int"))

      case Right((numValue, originalType)) =>
        val strValue = numValue match {
          case Left(floatValue) => f"$floatValue%.${precision}f"
          case Right(decimalValue) => s"${decimalValue.formatted(s"%%.%$${precision}f")}"
        }
        Token(strValue, TokenType.NUMERIC, Map("originalType" -> originalType))
    }
  }

  // Convenience methods for different numeric types
  def tokenizeInt(value: Int): Token = tokenize(Left(value))
  def tokenizeFloat(value: Float): Token = tokenize(Right((Left(value), "Float")))
  def tokenizeDouble(value: Double): Token = tokenize(Right((Left(value.toFloat), "Double")))
  def tokenizeBigDecimal(value: BigDecimal): Token = tokenize(Right((Right(value), "BigDecimal")))
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Either[java.time.LocalDateTime, java.time.LocalDate]] {

  val IsoFormat = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat = "yyyy-MM-dd"

  override def tokenize(value: Either[java.time.LocalDateTime, java.time.LocalDate]): Token = {
    val formatted = value match {
      case Left(dateTime) =>
        formatStr.getOrElse(IsoFormat)
        dateTime.format(java.time.format.DateTimeFormatter.ofPattern(formatStr.getOrElse(IsoFormat)))

      case Right(date) =>
        date.format(java.time.format.DateTimeFormatter.ofPattern(formatStr.getOrElse(DateFormat)))
    }
    Token(formatted, TokenType.TEMPORAL)
  }
}

/**
 * Tokenizer that handles multiple types with pattern matching.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
   * Dispatch to appropriate tokenizer based on runtime type.
   */
  def tokenize(value: Any): Token = {
    value match {
      case null => Token("NULL", TokenType.NULL)

      case tokenizable: Tokenizable =>
        Token(tokenizable.toToken, TokenType.STRUCTURED)

      case str: String =>
        stringTokenizer.tokenize(Left(str))

      case bytes: Array[Byte] =>
        stringTokenizer.tokenize(Right(bytes))

      case int: Int =>
        numericTokenizer.tokenizeInt(int)

      case float: Float =>
        numericTokenizer.tokenizeFloat(float)

      case double: Double =>
        numericTokenizer.tokenizeDouble(double)

      case decimal: BigDecimal =>
        numericTokenizer.tokenizeBigDecimal(decimal)

      case dateTime: java.time.LocalDateTime =>
        temporalTokenizer.tokenize(Left(dateTime))

      case date: java.time.LocalDate =>
        temporalTokenizer.tokenize(Right(date))

      // Fallback: try toString conversion
      case _ =>
        Token(value.toString, TokenType.STRING, Map("fallback" -> true))
    }
  }
}

/**
 * Registry with complex nested generic types.
 */
class TokenRegistry[T] {
  private val _registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val _handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.toList.flatMap(handler => handler(item)).headOption
        }.toList
    }
  }
}

/**
 * Functor for tokens.
 */
class TokenFunctor[+T](val value: T) {
  def map[A](func: T => A): TokenFunctor[A] = new TokenFunctor(func(value))

  def flatMap[A](func: T => TokenFunctor[A]): TokenFunctor[A] = func(value)

  def getOrElse(default: T): T = Option(value).getOrElse(default)
}

/**
 * Extended monad operations.
 */
class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)

  def ap[A](funcWrapped: TokenMonad[T => A]): TokenMonad[A] = {
    val func = funcWrapped.value
    new TokenMonad(func(value))
  }
}

object TokenMonad {
  def apply[T](value: T): TokenMonad[T] = new TokenMonad(value)
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

/**
 * Represents JSON values with recursive type definition.
 */
sealed trait JsonValue

object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case class JsonNull() extends JsonValue
  case class JsonArray(items: List[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) prettyPrint(value) else compactPrint(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /**
   * Extract and tokenize a value at a JSON path.
   */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    val result = parts.foldLeft[Option[JsonValue]](Some(value)) { (current, part) =>
      current.flatMap {
        case JsonObject(fields) => fields.get(part)
        case JsonArray(items) =>
          if (part.forall(_.isDigit)) {
            val idx = part.toIntOption
            idx.flatMap(i => items.lift(i))
          } else None
        case _ => None
      }
    }
    result.map(tokenize)
  }

  private def compactPrint(value: JsonValue): String = value match {
    case JsonString(s) => s""""$s""""
    case JsonNumber(n) => n.toString
    case JsonBoolean(b) => b.toString
    case JsonNull() => "null"
    case JsonArray(items) => items.map(compactPrint).mkString("[", ",", "]")
    case JsonObject(fields) =>
      fields.map { case (k, v) => s""""$k":${compactPrint(v)}""" }.mkString("{", ",", "}")
  }

  private def prettyPrint(value: JsonValue): String = {
    def pretty(value: JsonValue, indent: Int): String = value match {
      case JsonString(s) => s""""$s""""
      case JsonNumber(n) => n.toString
      case JsonBoolean(b) => b.toString
      case JsonNull() => "null"
      case JsonArray(items) =>
        if (items.isEmpty) "[]"
        else {
          val indented = items.map(i => " " * (indent + 2) + pretty(i, indent + 2)).mkString("[\n", ",\n", s"\n${" " * indent}]")
          indented
        }
      case JsonObject(fields) =>
        if (fields.isEmpty) "{}"
        else {
          val indented = fields.map { case (k, v) =>
            s"""${" " * (indent + 2)}"$k": ${pretty(v, indent + 2)}"""
          }.mkString("{\n", ",\n", s"\n${" " * indent}}")
          indented
        }
    }
    pretty(value, 0)
  }
}

/**
 * Basic tokenizer that splits text by whitespace.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set(',', '.', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    val processed = if (stripPunctuation) {
      word.dropWhile(punctuation.contains).dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    } else word

    val normalized = if (lowercase) processed.toLowerCase else processed

    if (normalized.length < minLength) None
    else maxLength match {
      case Some(max) if normalized.length > max => Some(normalized.take(max))
      case _ => if (normalized.nonEmpty) Some(normalized) else None
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    text.split("\\s+").zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map(processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      )
    }.toList
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

/**
 * Fluent builder for creating tokenizers.
 */
class TokenizerBuilder[T] {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[T => Boolean] = mutable.ListBuffer.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(additionalMetadata: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ additionalMetadata.toMap
    this
  }

  def build: T => Token = { value: T =>
    // Validate
    validators.find(!_(value)).foreach { _ =>
      throw new IllegalArgumentException(s"Validation failed for $value")
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.STRING, metadata)
  }
}

/**
 * Convenience functions for common tokenization operations.
 */
object Tokenizer {
  private val universalTokenizer = new UniversalTokenizer()

  /**
   * Tokenize a single value using the universal tokenizer.
   */
  def tokenize(value: Any): Token = {
    universalTokenizer.tokenize(value)
  }

  /**
   * Tokenize a batch of values.
   */
  def tokenizeBatch(values: Iterable[Any]): List[Token] = {
    values.map(tokenize).toList
  }

  /**
   * Convert a value to a Token.
   */
  def toToken(value: String, tokenType: TokenType, metadata: (String, Any)*): Token = {
    Token(value, tokenType, metadata.toMap)
  }

  /**
   * Add metadata to an existing token.
   */
  def withMetadata(token: Token, metadata: (String, Any)*): Token = {
    token.withMetadata(metadata: _*)
  }

  /**
   * Create a String tokenizer.
   */
  def stringTokenizer(encoding: String = "utf-8")(normalizer: String => String = identity): StringTokenizer = {
    new StringTokenizer(encoding, normalizer)
  }

  /**
   * Create a Numeric tokenizer.
   */
  def numericTokenizer(precision: Int = 6)(formatOptions: (String, Any)*): NumericTokenizer = {
    new NumericTokenizer(precision, formatOptions.toMap)
  }

  /**
   * Create a Temporal tokenizer.
   */
  def temporalTokenizer(formatStr: String = "yyyy-MM-dd"): TemporalTokenizer = {
    new TemporalTokenizer(Some(formatStr))
  }

  /**
   * Create a Universal tokenizer.
   */
  def createUniversalTokenizer: UniversalTokenizer = new UniversalTokenizer()

  /**
   * Create a Whitespace tokenizer.
   */
  def whitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ): WhitespaceTokenizer = {
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
  }

  /**
   * Create a Json tokenizer.
   */
  def jsonTokenizer(pretty: Boolean = false): JsonTokenizer = {
    new JsonTokenizer(pretty)
  }

  /**
   * Create a Tokenizer builder.
   */
  def builder[T]: TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

